        reg_rdata_next[2:0] = ses_window_stage_3_qs;
      end

      addr_hit[19]: begin
        reg_rdata_next[2:0] = ses_window_stage_4_qs;
      end

      addr_hit[20]: begin
        reg_rdata_next[2:0] = ses_window_stage_5_qs;
      end

      addr_hit[21]: begin
        reg_rdata_next[2:0] = ses_window_stage_6_qs;
      end

      addr_hit[22]: begin
        reg_rdata_next[2:0] = ses_window_stage_7_qs;
      end

      addr_hit[23]: begin
        reg_rdata_next[2:0] = ses_window_stage_8_qs;
      end

      addr_hit[24]: begin
        reg_rdata_next[2:0] = ses_window_stage_9_qs;
      end

      addr_hit[25]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_0_qs;
      end

      addr_hit[26]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_1_qs;
      end

      addr_hit[27]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_2_qs;
      end

      addr_hit[28]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_3_qs;
      end

      addr_hit[29]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_4_qs;
      end

      addr_hit[30]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_5_qs;
      end

      addr_hit[31]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_6_qs;
      end

      addr_hit[32]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_7_qs;
      end

      addr_hit[33]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_8_qs;
      end

      addr_hit[34]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_9_qs;
      end

      addr_hit[35]: begin
        reg_rdata_next[2:0] = ses_decimation_factor_stage_10_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule

module ses_filter_reg_top_intf #(
    parameter  int AW = 8,
    localparam int DW = 32
) (
    input logic clk_i,
    input logic rst_ni,
    REG_BUS.in regbus_slave,
    // To HW
    output ses_filter_reg_pkg::ses_filter_reg2hw_t reg2hw,  // Write
    input ses_filter_reg_pkg::ses_filter_hw2reg_t hw2reg,  // Read
    // Config
    input devmode_i  // If 1, explicit error return for unmapped register access
);
  localparam int unsigned STRB_WIDTH = DW / 8;

  `include "register_interface/typedef.svh"
  `include "register_interface/assign.svh"

  // Define structs for reg_bus
  typedef logic [AW-1:0] addr_t;
  typedef logic [DW-1:0] data_t;
  typedef logic [STRB_WIDTH-1:0] strb_t;
  `REG_BUS_TYPEDEF_ALL(reg_bus, addr_t, data_t, strb_t)

  reg_bus_req_t s_reg_req;
  reg_bus_rsp_t s_reg_rsp;

  // Assign SV interface to structs
  `REG_BUS_ASSIGN_TO_REQ(s_reg_req, regbus_slave)
  `REG_BUS_ASSIGN_FROM_RSP(regbus_slave, s_reg_rsp)



  ses_filter_reg_top #(
      .reg_req_t(reg_bus_req_t),
      .reg_rsp_t(reg_bus_rsp_t),
      .AW(AW)
  ) i_regs (
      .clk_i,
      .rst_ni,
      .reg_req_i(s_reg_req),
      .reg_rsp_o(s_reg_rsp),
      .reg2hw,  // Write
      .hw2reg,  // Read
      .devmode_i
  );

endmodule


